from checkov.terraform.checks.resource.gcp.GKEBasicAuth import check
from checkov.common.models.enums import CheckResult

def test_case(name, resource_conf, expected_result):
    """Helper function to test a configuration."""
    print(f"\nTesting {name}...")
    result = check.scan_resource_conf(conf=resource_conf)
    print(f"Result: {result}, Expected: {expected_result}")

    if result == expected_result:
        print("✅ PASS")
        return True
    else:
        print("❌ FAIL")
        return False

def main():
    print("Testing edge cases for GKEBasicAuth fix...")

    all_passed = True

    # Test 1: Empty username, no password field
    all_passed &= test_case(
        "empty username, no password",
        {
            'master_auth': [{
                'username': ['']
            }]
        },
        CheckResult.PASSED
    )

    # Test 2: No username, empty password
    all_passed &= test_case(
        "no username, empty password", 
        {
            'master_auth': [{
                'password': ['']
            }]
        },
        CheckResult.PASSED
    )

    # Test 3: Empty username, no password (None)
    all_passed &= test_case(
        "empty username, no password field",
        {
            'master_auth': [{
                'username': ['']
                # no password field
            }]
        },
        CheckResult.PASSED
    )

    # Test 4: Non-empty username, empty password
    all_passed &= test_case(
        "non-empty username, empty password",
        {
            'master_auth': [{
                'username': ['admin'],
                'password': ['']
            }]
        },
        CheckResult.FAILED
    )

    # Test 5: Empty username, non-empty password
    all_passed &= test_case(
        "empty username, non-empty password",
        {
            'master_auth': [{
                'username': [''],
                'password': ['secret123']
            }]
        },
        CheckResult.FAILED
    )

    # Test 6: Both non-empty
    all_passed &= test_case(
        "both non-empty",
        {
            'master_auth': [{
                'username': ['admin'],
                'password': ['secret123']
            }]
        },
        CheckResult.FAILED
    )

    # Test 7: Neither field present (only client cert config)
    all_passed &= test_case(
        "neither field present",
        {
            'master_auth': [{
                'client_certificate_config': [{
                    'issue_client_certificate': [False]
                }]
            }]
        },
        CheckResult.PASSED
    )

    return all_passed

if __name__ == "__main__":
    if main():
        print("\n🎉 All edge case tests passed!")
        sys.exit(0)
    else:
